using System;
using UnityEngine;
using Framework.Grid;

namespace Framework.Movement
{
    /// <summary>
    /// グリッド上の連続移動を管理する汎用コンポーネント。
    ///
    /// 上下左右の移動、方向入力予約、移動可能判定、
    /// マス到達通知、一時停止などに対応する。
    ///
    /// 入力デバイスやゲーム固有のマップデータには依存しない。
    /// </summary>
    [DisallowMultipleComponent]
    public class GridMovementController : MonoBehaviour
    {
        #region Inspector Fields

        [Header("移動設定")]

        /// <summary>
        /// 1秒間に移動するマス数。
        /// </summary>
        [SerializeField]
        [Min(0f)]
        [Tooltip("1秒間に移動するマス数")]
        private float moveSpeed = 5f;

        /// <summary>
        /// 移動処理をUpdateで自動実行するか。
        /// </summary>
        [SerializeField]
        [Tooltip("Updateで移動処理を自動実行する")]
        private bool autoUpdate = true;

        /// <summary>
        /// 1回の移動処理で通過できる最大マス数。
        /// 極端に大きな時間や速度による負荷を防止する。
        /// </summary>
        [SerializeField]
        [Min(1)]
        [Tooltip("1回の移動処理で通過できる最大マス数")]
        private int maxStepsPerTick = 128;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// グリッド座標とワールド座標の変換システム。
        /// </summary>
        private GridCoordinateConverter coordinateConverter;

        /// <summary>
        /// 指定されたマスへの移動が可能か判定する関数。
        /// 範囲外や壁の場合はfalseを返す必要がある。
        /// </summary>
        private Func<Vector2Int, bool> walkablePredicate;

        /// <summary>
        /// 最後に到達したマスの座標。
        /// 移動途中では出発元のマスを表す。
        /// </summary>
        private Vector2Int currentCell;

        /// <summary>
        /// 現在向かっているマスの座標。
        /// </summary>
        private Vector2Int targetCell;

        /// <summary>
        /// 現在の移動方向。
        /// </summary>
        private Vector2Int currentDirection;

        /// <summary>
        /// 次に移動したい予約方向。
        /// </summary>
        private Vector2Int requestedDirection;

        /// <summary>
        /// 現在のマス間移動の進捗率（0～1）。
        /// </summary>
        private float segmentProgress;

        /// <summary>
        /// マス間を移動しているか。
        /// </summary>
        private bool isTraversing;

        /// <summary>
        /// 連続移動中か。
        /// </summary>
        private bool isMoving;

        /// <summary>
        /// 移動システムが初期化されているか。
        /// </summary>
        private bool isInitialized;

        /// <summary>
        /// 移動処理が一時停止されているか。
        /// </summary>
        private bool isPaused;

        /// <summary>
        /// 次のマス中心で停止するか。
        /// </summary>
        private bool stopRequested;

        /// <summary>
        /// マス中心からのZ座標補正値。
        /// </summary>
        private float zOffset;

        /// <summary>
        /// 移動処理の再入を防止するフラグ。
        /// </summary>
        private bool isTicking;

        /// <summary>
        /// 初期化や瞬間移動による状態変更を検出する番号。
        /// </summary>
        private int movementVersion;

        #endregion

        #region Properties

        /// <summary>
        /// 移動システムが初期化されているか。
        /// </summary>
        public bool IsInitialized => isInitialized;

        /// <summary>
        /// 連続移動中か。
        /// 一時停止中も移動状態自体は維持される。
        /// </summary>
        public bool IsMoving => isMoving;

        /// <summary>
        /// 一時停止中か。
        /// </summary>
        public bool IsPaused => isPaused;

        /// <summary>
        /// マス間を移動しているか。
        /// </summary>
        public bool IsTraversing => isTraversing;

        /// <summary>
        /// 現在マスの中心にいるか。
        /// </summary>
        public bool IsAtCellCenter =>
            isInitialized && !isTraversing;

        /// <summary>
        /// 最後に到達したマスの座標。
        /// </summary>
        public Vector2Int CurrentCell => currentCell;

        /// <summary>
        /// 現在向かっているマスの座標。
        /// 停止中はCurrentCellと同じ値を返す。
        /// </summary>
        public Vector2Int TargetCell => targetCell;

        /// <summary>
        /// 現在の移動方向。
        /// </summary>
        public Vector2Int CurrentDirection =>
            currentDirection;

        /// <summary>
        /// 現在予約されている移動方向。
        /// </summary>
        public Vector2Int RequestedDirection =>
            requestedDirection;

        /// <summary>
        /// 予約方向が存在するか。
        /// </summary>
        public bool HasRequestedDirection =>
            requestedDirection != Vector2Int.zero;

        /// <summary>
        /// マス間移動の進捗率（0～1）。
        /// </summary>
        public float SegmentProgress =>
            segmentProgress;

        /// <summary>
        /// 1秒間に移動するマス数。
        /// </summary>
        public float MoveSpeed
        {
            get => moveSpeed;

            set
            {
                if (float.IsNaN(value) ||
                    float.IsInfinity(value) ||
                    value < 0f)
                {
                    throw new ArgumentOutOfRangeException(
                        nameof(value),
                        "移動速度には0以上の有限値を指定してください。");
                }

                moveSpeed = value;
            }
        }

        /// <summary>
        /// Updateによる自動移動処理の有効状態。
        /// </summary>
        public bool AutoUpdate
        {
            get => autoUpdate;
            set => autoUpdate = value;
        }

        /// <summary>
        /// マス中心からのZ座標補正値。
        /// </summary>
        public float ZOffset => zOffset;

        #endregion

        #region Events

        /// <summary>
        /// 停止状態から移動を開始した際の通知。
        /// 引数：移動開始マスの座標。
        /// </summary>
        public event Action<Vector2Int> MovementStarted;

        /// <summary>
        /// マス中心に到達した際の通知。
        /// 引数：到達したマスの座標。
        /// </summary>
        public event Action<Vector2Int> CellReached;

        /// <summary>
        /// 移動方向が変更された際の通知。
        /// 引数：変更前の方向、変更後の方向。
        /// </summary>
        public event Action<Vector2Int, Vector2Int>
            DirectionChanged;

        /// <summary>
        /// 移動を停止した際の通知。
        /// 引数：停止したマスの座標。
        /// </summary>
        public event Action<Vector2Int> MovementStopped;

        /// <summary>
        /// 一時停止状態が変更された際の通知。
        /// 引数：変更後の一時停止状態。
        /// </summary>
        public event Action<bool> PauseChanged;

        /// <summary>
        /// 瞬間移動が実行された際の通知。
        /// 引数：移動前のマス、移動後のマス。
        /// </summary>
        public event Action<Vector2Int, Vector2Int>
            Teleported;

        #endregion

        #region Unity Methods

        /// <summary>
        /// 毎フレームの移動処理。
        /// </summary>
        private void Update()
        {
            if (autoUpdate)
            {
                Tick(Time.deltaTime);
            }
        }

        /// <summary>
        /// Inspectorからの設定値を補正する。
        /// </summary>
        private void OnValidate()
        {
            if (float.IsNaN(moveSpeed) ||
                float.IsInfinity(moveSpeed))
            {
                moveSpeed = 5f;
            }

            moveSpeed = Mathf.Max(0f, moveSpeed);

            maxStepsPerTick =
                Mathf.Max(1, maxStepsPerTick);
        }

        #endregion

        #region Initialization Methods

        /// <summary>
        /// 移動システムを初期化する。
        /// </summary>
        /// <param name="converter">
        /// グリッド座標変換システム
        /// </param>
        /// <param name="canEnterCell">
        /// 指定マスへの移動可能判定
        /// </param>
        /// <param name="startCell">
        /// 初期配置マス
        /// </param>
        /// <param name="initialZOffset">
        /// マス中心からのZ座標補正値
        /// </param>
        public void Initialize(
            GridCoordinateConverter converter,
            Func<Vector2Int, bool> canEnterCell,
            Vector2Int startCell,
            float initialZOffset = 0f)
        {
            if (converter == null)
            {
                throw new ArgumentNullException(
                    nameof(converter));
            }

            if (canEnterCell == null)
            {
                throw new ArgumentNullException(
                    nameof(canEnterCell));
            }

            if (!canEnterCell(startCell))
            {
                throw new ArgumentException(
                    "初期配置マスには移動できません。",
                    nameof(startCell));
            }

            coordinateConverter = converter;
            walkablePredicate = canEnterCell;
            zOffset = initialZOffset;

            movementVersion++;

            currentCell = startCell;
            targetCell = startCell;

            currentDirection = Vector2Int.zero;
            requestedDirection = Vector2Int.zero;

            segmentProgress = 0f;

            isTraversing = false;
            isMoving = false;
            isPaused = false;
            stopRequested = false;

            isInitialized = true;

            // 初期配置マスの中心へ移動する。
            transform.position =
                GetCellWorldPosition(startCell);
        }

        #endregion

        #region Direction Methods

        /// <summary>
        /// 指定された方向への移動を予約する。
        ///
        /// マス中心にいる場合は次回の移動処理で採用され、
        /// 移動途中の場合は次のマス中心まで保持される。
        /// </summary>
        /// <param name="direction">
        /// 上下左右いずれかの単位方向
        /// </param>
        /// <returns>予約に成功した場合はtrue</returns>
        public bool RequestDirection(Vector2Int direction)
        {
            if (!isInitialized ||
                !IsCardinalDirection(direction))
            {
                return false;
            }

            requestedDirection = direction;

            // 新しい移動指示によって停止予約を解除する。
            stopRequested = false;

            return true;
        }

        /// <summary>
        /// 現在の方向予約を解除する。
        /// 現在進行中の移動には影響しない。
        /// </summary>
        public void ClearRequestedDirection()
        {
            requestedDirection = Vector2Int.zero;
        }

        /// <summary>
        /// 指定方向が上下左右の単位方向か確認する。
        /// </summary>
        /// <param name="direction">確認する方向</param>
        /// <returns>有効な4方向の場合はtrue</returns>
        public static bool IsCardinalDirection(
            Vector2Int direction)
        {
            return direction == Vector2Int.up ||
                   direction == Vector2Int.down ||
                   direction == Vector2Int.left ||
                   direction == Vector2Int.right;
        }

        /// <summary>
        /// 指定マスへ移動可能か確認する。
        /// </summary>
        /// <param name="position">確認するマス</param>
        /// <returns>移動可能な場合はtrue</returns>
        public bool CanEnterCell(Vector2Int position)
        {
            return isInitialized &&
                   walkablePredicate != null &&
                   walkablePredicate(position);
        }

        /// <summary>
        /// 現在マスから指定方向へ移動可能か確認する。
        /// </summary>
        /// <param name="direction">確認する方向</param>
        /// <returns>移動可能な場合はtrue</returns>
        public bool CanMove(Vector2Int direction)
        {
            return IsCardinalDirection(direction) &&
                   CanEnterCell(currentCell + direction);
        }

        #endregion

        #region Movement Methods

        /// <summary>
        /// 指定された時間分だけ移動処理を実行する。
        ///
        /// 複数マスを通過する場合も、
        /// 各マス中心で方向判定と到達通知を行う。
        /// </summary>
        /// <param name="deltaTime">経過時間（秒）</param>
        public void Tick(float deltaTime)
        {
            if (!isInitialized ||
                isPaused ||
                isTicking ||
                deltaTime <= 0f ||
                float.IsNaN(deltaTime) ||
                float.IsInfinity(deltaTime))
            {
                return;
            }

            isTicking = true;

            int version = movementVersion;

            try
            {
                // 未消費の移動時間を保持する。
                float remainingTime = deltaTime;

                // この処理中に到達したマス数。
                int completedSteps = 0;

                while (remainingTime > 0f &&
                       completedSteps < maxStepsPerTick)
                {
                    if (isPaused ||
                        version != movementVersion ||
                        moveSpeed <= 0f)
                    {
                        break;
                    }

                    // マス中心の場合は次の移動先を決定する。
                    if (!isTraversing)
                    {
                        if (!TryBeginNextSegment())
                        {
                            break;
                        }
                    }

                    // イベント内で停止や瞬間移動が
                    // 実行された場合は処理を中断する。
                    if (isPaused ||
                        version != movementVersion ||
                        !isTraversing ||
                        moveSpeed <= 0f)
                    {
                        break;
                    }

                    // 現在のマス間移動に必要な残り時間。
                    float timeToTarget =
                        (1f - segmentProgress) / moveSpeed;

                    if (remainingTime < timeToTarget)
                    {
                        // 今回の時間では次のマスに到達しない。
                        segmentProgress = Mathf.Clamp01(
                            segmentProgress +
                            moveSpeed * remainingTime);

                        remainingTime = 0f;

                        UpdateWorldPosition();
                    }
                    else
                    {
                        // 次のマス中心まで移動する。
                        remainingTime -= timeToTarget;

                        CompleteSegment();

                        completedSteps++;

                        if (version != movementVersion ||
                            isPaused)
                        {
                            break;
                        }

                        // 停止予約または進行不能の場合は停止する。
                        // 予約方向が通行可能なら移動を継続する。
                        if (stopRequested ||
                            !HasAvailableDirection())
                        {
                            FinishMovement();
                            break;
                        }
                    }
                }
            }
            finally
            {
                isTicking = false;
            }
        }

        /// <summary>
        /// 次のマス間移動を開始する。
        /// </summary>
        /// <returns>移動開始に成功した場合はtrue</returns>
        private bool TryBeginNextSegment()
        {
            if (stopRequested)
            {
                FinishMovement();
                return false;
            }

            Vector2Int nextDirection =
                GetNextDirection();

            if (nextDirection == Vector2Int.zero)
            {
                FinishMovement();
                return false;
            }

            Vector2Int previousDirection =
                currentDirection;

            bool wasMoving = isMoving;

            int version = movementVersion;

            // 次の移動先と方向を確定する。
            currentDirection = nextDirection;
            targetCell = currentCell + nextDirection;

            segmentProgress = 0f;

            isTraversing = true;
            isMoving = true;

            // 採用した予約方向を消費する。
            if (requestedDirection == nextDirection)
            {
                requestedDirection = Vector2Int.zero;
            }

            if (!wasMoving)
            {
                MovementStarted?.Invoke(currentCell);
            }

            if (version != movementVersion)
            {
                return false;
            }

            if (previousDirection != currentDirection)
            {
                DirectionChanged?.Invoke(
                    previousDirection,
                    currentDirection);
            }

            return version == movementVersion;
        }

        /// <summary>
        /// 次に採用する移動方向を取得する。
        ///
        /// 予約方向を優先し、移動できない場合は
        /// 現在の方向への移動継続を試みる。
        /// </summary>
        /// <returns>次の移動方向。移動不能時はzero</returns>
        private Vector2Int GetNextDirection()
        {
            if (CanMove(requestedDirection))
            {
                return requestedDirection;
            }

            if (CanMove(currentDirection))
            {
                return currentDirection;
            }

            return Vector2Int.zero;
        }

        /// <summary>
        /// 現在マスから継続可能な方向が存在するか。
        /// </summary>
        /// <returns>移動可能な方向がある場合はtrue</returns>
        private bool HasAvailableDirection()
        {
            return GetNextDirection() != Vector2Int.zero;
        }

        /// <summary>
        /// 現在の移動進捗に基づいて
        /// ワールド座標を更新する。
        /// </summary>
        private void UpdateWorldPosition()
        {
            Vector3 startPosition =
                GetCellWorldPosition(currentCell);

            Vector3 targetPosition =
                GetCellWorldPosition(targetCell);

            transform.position = Vector3.Lerp(
                startPosition,
                targetPosition,
                segmentProgress);
        }

        /// <summary>
        /// 次のマスへの到達処理を行う。
        /// </summary>
        private void CompleteSegment()
        {
            currentCell = targetCell;

            segmentProgress = 0f;
            isTraversing = false;

            // 誤差が蓄積しないようマス中心に固定する。
            transform.position =
                GetCellWorldPosition(currentCell);

            // 外部の取得処理やAIへ到達を通知する。
            CellReached?.Invoke(currentCell);
        }

        /// <summary>
        /// 指定マスのワールド中心座標を取得する。
        /// </summary>
        /// <param name="position">対象マス</param>
        /// <returns>Z補正を含むワールド座標</returns>
        private Vector3 GetCellWorldPosition(
            Vector2Int position)
        {
            Vector3 worldPosition =
                coordinateConverter.GetCellCenterWorld(
                    position);

            worldPosition.z += zOffset;

            return worldPosition;
        }

        #endregion

        #region Stop Methods

        /// <summary>
        /// 次のマス中心で停止するよう予約する。
        ///
        /// 既にマス中心にいる場合は即座に停止する。
        /// </summary>
        public void RequestStop()
        {
            if (!isInitialized)
            {
                return;
            }

            requestedDirection = Vector2Int.zero;

            stopRequested = true;

            if (!isTraversing)
            {
                FinishMovement();
            }
        }

        /// <summary>
        /// 移動を即座に停止する。
        ///
        /// 移動途中の場合は最後に到達したマスへ戻る。
        /// </summary>
        public void StopImmediately()
        {
            if (!isInitialized)
            {
                return;
            }

            movementVersion++;

            requestedDirection = Vector2Int.zero;

            transform.position =
                GetCellWorldPosition(currentCell);

            FinishMovement();
        }

        /// <summary>
        /// 移動状態を終了して停止通知を発行する。
        /// </summary>
        private void FinishMovement()
        {
            bool wasMoving = isMoving;

            Vector2Int previousDirection =
                currentDirection;

            isMoving = false;
            isTraversing = false;
            stopRequested = false;

            currentDirection = Vector2Int.zero;

            targetCell = currentCell;
            segmentProgress = 0f;

            int version = movementVersion;

            if (previousDirection != Vector2Int.zero)
            {
                DirectionChanged?.Invoke(
                    previousDirection,
                    Vector2Int.zero);
            }

            if (wasMoving &&
                version == movementVersion)
            {
                MovementStopped?.Invoke(currentCell);
            }
        }

        #endregion

        #region Pause Methods

        /// <summary>
        /// 移動処理の一時停止状態を設定する。
        /// マス間の移動進捗や予約方向は維持される。
        /// </summary>
        /// <param name="paused">一時停止する場合はtrue</param>
        public void SetPaused(bool paused)
        {
            if (isPaused == paused)
            {
                return;
            }

            isPaused = paused;

            PauseChanged?.Invoke(isPaused);
        }

        /// <summary>
        /// 移動処理を一時停止する。
        /// </summary>
        public void Pause()
        {
            SetPaused(true);
        }

        /// <summary>
        /// 移動処理を再開する。
        /// </summary>
        public void Resume()
        {
            SetPaused(false);
        }

        #endregion

        #region Teleport Methods

        /// <summary>
        /// 指定されたマスへ瞬間移動する。
        ///
        /// 移動方向と予約方向を初期化する。
        /// CellReachedイベントは発行しない。
        /// </summary>
        /// <param name="position">瞬間移動先のマス</param>
        /// <returns>瞬間移動に成功した場合はtrue</returns>
        public bool TryTeleport(Vector2Int position)
        {
            if (!CanEnterCell(position))
            {
                return false;
            }

            Vector2Int previousCell = currentCell;

            bool wasMoving = isMoving;

            Vector2Int previousDirection =
                currentDirection;

            movementVersion++;

            int version = movementVersion;

            currentCell = position;
            targetCell = position;

            currentDirection = Vector2Int.zero;
            requestedDirection = Vector2Int.zero;

            segmentProgress = 0f;

            isTraversing = false;
            isMoving = false;
            stopRequested = false;

            transform.position =
                GetCellWorldPosition(position);

            if (previousDirection != Vector2Int.zero)
            {
                DirectionChanged?.Invoke(
                    previousDirection,
                    Vector2Int.zero);
            }

            if (version != movementVersion)
            {
                return true;
            }

            if (wasMoving)
            {
                MovementStopped?.Invoke(position);
            }

            if (version == movementVersion)
            {
                Teleported?.Invoke(
                    previousCell,
                    position);
            }

            return true;
        }

        #endregion
    }
}
